def anti_shuffle(s):
    import re
    words = re.split(r'(\s+)', s)
    ordered_words = []
    for word in words:
        if word.strip():
            ordered = ''.join(sorted(word))
            ordered_words.append(ordered)
        else:
            ordered_words.append(word)
    return ''.join(ordered_words)
